def compute(vars):
    due_2018 = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    portion = due_2018 / total_obligations
    return {
        "value": portion,
        "trace": {
            "due_2018": due_2018,
            "total_obligations": total_obligations,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
